"""Read-only situational-awareness CLI for the open-ended swarm.

No dependencies. Tolerates empty, JSON, JSONL, and partially-written shared logs.
Usage: python3 agent-010_swarmmap_*.py [--root PATH] [--json] [--since MINUTES]
"""
from __future__ import annotations
import argparse, collections, datetime as dt, json, pathlib, re, sys

AGENT_RE = re.compile(r"agent-\d{3}")


def parse_objects(path: pathlib.Path):
    """Best-effort parse of a shared JSON/JSONL file without ever modifying it."""
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return []
    if not text.strip():
        return []
    try:
        value = json.loads(text)
        if isinstance(value, list):
            return [x for x in value if isinstance(x, dict)]
        return [value] if isinstance(value, dict) else []
    except json.JSONDecodeError:
        out = []
        for line in text.splitlines():
            try:
                value = json.loads(line)
                if isinstance(value, dict): out.append(value)
            except json.JSONDecodeError:
                pass  # likely a concurrent partial append
        return out


def iso_age_minutes(value, now):
    if not value: return None
    try:
        parsed = dt.datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        if parsed.tzinfo is None: parsed = parsed.replace(tzinfo=dt.timezone.utc)
        return max(0, (now-parsed.astimezone(dt.timezone.utc)).total_seconds()/60)
    except (ValueError, TypeError):
        return None


def owner(path):
    match = AGENT_RE.search(path.name)
    return match.group(0) if match else "unknown"

