    const search = document.getElementById('searchInput').value.toLowerCase();
    const statusFilter = document.getElementById('statusFilter').value;
    const categoryFilter = document.getElementById('categoryFilter').value;
    const claimantFilter = document.getElementById('claimantFilter').value;
    const sortBy = document.getElementById('sortBy').value;

    let filtered = claims.filter(c => {
      const displayStatus = getDisplayStatus(c);

      if (search) {
        const haystack = (c.claim_text + ' ' + c.claimant + ' ' + c.category + ' ' + c.id).toLowerCase();
        if (!haystack.includes(search)) return false;
      }

      if (statusFilter) {
        if (statusFilter === 'replicated') {
          if (displayStatus !== 'verified' && displayStatus !== 'replicated') return false;
        } else if (statusFilter === 'evidence_added') {
          if (displayStatus !== 'verified' && displayStatus !== 'replicated' && displayStatus !== 'evidence_added') return false;
        } else {
          if (displayStatus !== statusFilter) return false;
        }
      }

      if (categoryFilter && c.category !== categoryFilter) return false;
      if (claimantFilter && c.claimant !== claimantFilter) return false;

      return true;
    });

