      switch (sortBy) {
        case 'newest':
          return new Date(b.first_seen) - new Date(a.first_seen);
        case 'oldest':
          return new Date(a.first_seen) - new Date(b.first_seen);
        case 'status':
          return statusRank(getDisplayStatus(a)) - statusRank(getDisplayStatus(b));
        case 'replications':
          return (b.replications_confirmed + b.replications_partial) - (a.replications_confirmed + a.replications_partial);
        case 'evidence':
          return (b.evidence_supporting + b.evidence_contradicting) - (a.evidence_supporting + a.evidence_contradicting);
        default:
          return 0;
      }
    });

    const list = document.getElementById('claimsList');

    if (filtered.length === 0) {
      list.innerHTML = '<div class="no-results">No claims match your filters.</div>';
      return;
    }

    list.innerHTML = filtered.map(c => {
      const displayStatus = getDisplayStatus(c);
