        repHtml = c.replication_details.map(r => `
          <div class="replication-item replication-${r.result}">
            <strong>${r.agent}</strong>: ${r.result}
            ${r.files && r.files.length ? '· ' + r.files.length + ' evidence file(s)' : ''}
          </div>
        `).join('');
      }

      let evHtml = '';
      if (c.evidence_files && c.evidence_files.length > 0) {
        evHtml = '<ul class="evidence-list">' + c.evidence_files.slice(0, 5).map(f => 
          `<li><code>${f}</code></li>`
        ).join('') + '</ul>';
        if (c.evidence_files.length > 5) {
          evHtml += `<div style="color:var(--text-muted);font-size:12px;">+ ${c.evidence_files.length - 5} more...</div>`;
        }
      }

      return `
        <div class="claim-card" onclick="this.classList.toggle('expanded')">
          <div class="claim-header">
            <span class="claim-id">${c.id}</span>
            <div class="claim-text">${c.claim_text}</div>
            <span class="status-badge status-${displayStatus}">${statusLabel}</span>
          </div>
          <div class="claim-meta">
            <span>&#128100; ${c.claimant}</span>
            <span>&#128193; ${c.category.replace(/_/g, ' ')}</span>
            ${totalReps > 0 ? `<span>&#128260; ${totalReps} replication(s)</span>` : ''}
            ${c.evidence_supporting + c.evidence_contradicting > 0 ? 
              `<span>&#128203; ${c.evidence_supporting + c.evidence_contradicting} evidence</span>` : ''}
            <span>&#128197; ${c.first_seen.substring(0, 16).replace('T', ' ')}</span>
          </div>
          <div class="claim-detail">
            ${totalReps > 0 ? `
              <div class="detail-section">
                <div class="detail-label">Replications</div>
                ${repHtml}
              </div>
            ` : ''}
            ${c.evidence_files && c.evidence_files.length > 0 ? `
              <div class="detail-section">
                <div class="detail-label">Evidence Files</div>
                ${evHtml}
              </div>
            ` : ''}
            <div class="detail-section">
              <div class="detail-label">Event Timeline (${c.events.length} events)</div>
              <div class="events-timeline">
                ${c.events.slice(0, 5).map(e => `
                  <div class="event-item">
                    <strong>${e.type}</strong>
                    ${e.agent ? 'by ' + e.agent : ''}
                    ${e.time ? '· ' + e.time.substring(11, 19) + ' UTC' : ''}
                    ${e.new_status ? '→ ' + e.new_status : ''}
                    ${e.result ? '· ' + e.result : ''}
                  </div>
                `).join('')}
                ${c.events.length > 5 ? `<div style="padding-left:14px;color:var(--text-muted);">+ ${c.events.length - 5} more events</div>` : ''}
              </div>
            </div>
          </div>
        </div>
      `;
    }).join('');
  }

  // Attach event listeners
  document.getElementById('searchInput').addEventListener('input', renderClaims);
  document.getElementById('statusFilter').addEventListener('change', renderClaims);
  document.getElementById('categoryFilter').addEventListener('change', renderClaims);
  document.getElementById('claimantFilter').addEventListener('change', renderClaims);
  document.getElementById('sortBy').addEventListener('change', renderClaims);

  // Initial render
  renderClaims();
})();
