{"content": "#!/usr/bin/env python3
"""Generate data.js for the Claims Explorer from the claims registry."""

import json
import os
import sys
from datetime import datetime, timezone
from pathlib import Path


def find_swarm_root():
    """Find the swarm root directory."""
    script_dir = Path(__file__).resolve().parent
    # Walk up until we find commons/
    current = script_dir
    for _ in range(10):
        if (current / "commons").exists():
            return current
        current = current.parent
    return script_dir


def load_claims(claims_file):
    """Load and build claim state from JSONL event log."""
    events = []
    try:
        with open(claims_file, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if line:
                    events.append(json.loads(line))
    except FileNotFoundError:
        return []

    claims = {}
    for e in events:
        cid = e.get("claim_id", "unknown")
        if cid not in claims:
            claims[cid] = {
                "id": cid,
                "events": [],
                "status": "proposed",
                "claimant": "",
                "claim_text": "",
                "category": "",
                "evidence_supporting": 0,
                "evidence_contradicting": 0,
                "replications_confirmed": 0,
                "replications_partial": 0,
                "replications_contradicted": 0,
                "first_seen": "",
                "last_update": "",
                "evidence_files": [],
                "replication_details": []
            }

        c = claims[cid]
        c["events"].append(e)

        if e["type"] == "register":
            c["claimant"] = e.get("claimant", "")
            c["claim_text"] = e.get("claim_text", "")
            c["category"] = e.get("category", "")
            c["first_seen"] = e.get("time", "")
            for ev in e.get("evidence", []):
                c["evidence_supporting"] += 1
                c["evidence_files"].append(ev)
        elif e["type"] == "evidence":
            if e.get("supports", True):
                c["evidence_supporting"] += 1
            else:
                c["evidence_contradicting"] += 1
            for f in e.get("files", []):
                c["evidence_files"].append(f)
        elif e["type"] == "replicate":
            r = e.get("result", "confirmed")
            if r == "confirmed":
                c["replications_confirmed"] += 1
            elif r == "partial":
                c["replications_partial"] += 1
            else:
                c["replications_contradicted"] += 1
            c["replication_details"].append({
                "agent": e.get("agent", ""),
                "result": r,
                "files": e.get("files", []),
                "time": e.get("time", "")
            })
        elif e["type"] == "status_change":
            c["status"] = e.get("new_status", "")

        c["last_update"] = e.get("time", "")

    return list(claims.values())


def main():
    swarm_root = find_swarm_root()
    print(f"Swarm root: {swarm_root}")

    # Find claims registry file
    claims_dir = swarm_root / "commons" / "data"
    claims_files = sorted(claims_dir.glob("agent-032_claims_registry_*.jsonl"), reverse=True)

    if not claims_files:
        print("ERROR: No claims registry file found")
        sys.exit(1)

    claims_file = claims_files[0]
    print(f"Using claims registry: {claims_file.name}")

    claims = load_claims(claims_file)
    print(f"Loaded {len(claims)} claims")

    # Generate data.js
    output_dir = Path(__file__).resolve().parent
    data_js = f"""// Claims Explorer Data
// Generated: {datetime.now(timezone.utc).isoformat().replace('+00:00', 'Z')}
// Source: {claims_file.name}
const CLAIMS_DATA = {json.dumps(claims, indent=2, ensure_ascii=False)};
const TOTAL_CLAIMS = {len(claims)};
"""

    output_path = output_dir / "data.js"
    with open(output_path, "w", encoding="utf-8") as f:
        f.write(data_js)

    print(f"Written data.js ({len(data_js)} bytes)")
    print(f"  Verified: {sum(1 for c in claims if c['status'] == 'verified')}")
    print(f"  With replications: {sum(1 for c in claims if c['replications_confirmed'] > 0)}")
    print(f"  With evidence: {sum(1 for c in claims if c['evidence_supporting'] + c['evidence_contradicting'] > 0)}")


if __name__ == "__main__":
    main()
