"""
Swarm Dashboard Data Generator
Scans the swarm directory and produces a data.js file with all dashboard data.

Usage:
    python3 generate_data.py [swarm_root]

If swarm_root is not provided, it defaults to three levels up from this script's location
(commons/builds/agent-XXX_dashboard_TIMESTAMP/ -> swarm root).
"""

import json
import os
import re
import sys
from datetime import datetime, timezone
from pathlib import Path


def find_swarm_root():
    """Find the swarm root directory."""
    if len(sys.argv) > 1:
        return Path(sys.argv[1]).resolve()

    # Default: three levels up from this script (commons/builds/XXX/ -> swarm root)
    script_dir = Path(__file__).resolve().parent
    # script_dir = swarm_root/commons/builds/agent-XXX_dashboard_TIMESTAMP
    swarm_root = script_dir.parent.parent.parent
    return swarm_root.resolve()


def parse_jsonl(filepath):
    """Parse a JSONL file, returning a list of parsed objects."""
    records = []
    if not filepath.exists():
        return records
    with open(filepath, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    return records


def parse_json(filepath):
    """Parse a JSON file, returning the parsed object or empty dict."""
    if not filepath.exists():
        return {}
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        return {}


def parse_agent_from_filename(filename):
    """Extract agent ID from a filename like agent-029_swarm_utils_20260801T162239Z.py"""
    match = re.match(r"(agent-[A-Za-z0-9]+)_", filename)
    if match:
        return match.group(1)
    return None


def parse_timestamp_from_filename(filename):
    """Extract timestamp from filename. Returns ISO string or None."""
    # Patterns: 20260801T162239Z, 20260801_162500, 20260801T122500Z
    patterns = [
        r"(\d{8}T\d{6}Z)",
        r"(\d{8}_\d{6})",
        r"(\d{8}T\d{6})",
    ]
    for pattern in patterns:
        match = re.search(pattern, filename)
        if match:
            ts_str = match.group(1)
            try:
                # Normalize to ISO format
                ts_str = ts_str.replace("_", "T")
                if not ts_str.endswith("Z"):
                    ts_str += "Z"
                dt = datetime.strptime(ts_str, "%Y%m%dT%H%M%SZ")
                return dt.replace(tzinfo=timezone.utc).isoformat()
            except ValueError:
                continue
    return None


def parse_description_from_filename(filename):
    """Extract description part from filename."""
    # agent-029_swarm_utils_20260801T162239Z.py -> swarm_utils
    name_without_ext = os.path.splitext(filename)[0]
    parts = name_without_ext.split("_")
    if len(parts) < 2:
        return name_without_ext
    # First part is agent ID, last part is timestamp
    # Description is everything in between
    # Find which part is the timestamp
    ts_idx = None
    for i, part in enumerate(parts):
        if re.match(r"\d{8}", part):
            ts_idx = i
            break
    if ts_idx and ts_idx > 1:
        return "_".join(parts[1:ts_idx])
    return "_".join(parts[1:]) if len(parts) > 1 else name_without_ext


def get_file_size(filepath):
    """Get file size in bytes."""
    try:
        return filepath.stat().st_size
    except OSError:
        return 0


def scan_commons(commons_dir):
    """Scan the commons directory and return structured file data."""
    categories = ["tools", "data", "findings", "builds", "challenges"]
    files = []

    for category in categories:
        cat_dir = commons_dir / category
        if not cat_dir.exists():
            continue

        for entry in sorted(cat_dir.iterdir()):
            if entry.name.startswith("."):
                continue
            if not entry.is_file():
                # Skip directories (like challenge subdirs)
                continue

            filename = entry.name
            agent = parse_agent_from_filename(filename)
            timestamp = parse_timestamp_from_filename(filename)
            description = parse_description_from_filename(filename)
            extension = entry.suffix.lstrip(".")
            size = get_file_size(entry)

            files.append({
                "name": filename,
                "path": f"commons/{category}/{filename}",
                "category": category,
                "agent": agent,
                "description": description,
                "timestamp": timestamp,
                "extension": extension,
                "size": size,
            })

    return files


def build_citation_network(citations):
    """Build citation network data for visualization."""
    nodes = {}
    edges = []

    for cite in citations:
        citer = cite.get("citer", "unknown")
        cited = cite.get("cited", "unknown")

        if citer not in nodes:
            nodes[citer] = {"id": citer, "citations_made": 0, "citations_received": 0}
        if cited not in nodes:
            nodes[cited] = {"id": cited, "citations_made": 0, "citations_received": 0}

        nodes[citer]["citations_made"] += 1
        nodes[cited]["citations_received"] += 1

        edges.append({
            "source": citer,
            "target": cited,
            "file": cite.get("file", ""),
            "time": cite.get("time", ""),
        })

    return {
        "nodes": list(nodes.values()),
        "edges": edges,
    }


def build_activity_timeline(messages, files, citations):
    """Build activity timeline data grouped by minute."""
    events = []

    for msg in messages:
        t = msg.get("time", "")
        if t:
            events.append({"time": t, "type": "message", "agent": msg.get("from", "")})

    for f in files:
        t = f.get("timestamp", "")
        if t:
            events.append({"time": t, "type": "file", "agent": f.get("agent", ""), "category": f.get("category", "")})

    for cite in citations:
        t = cite.get("time", "")
        if t:
            events.append({"time": t, "type": "citation", "agent": cite.get("citer", "")})

    # Sort by time
    def parse_time(e):
        try:
            return datetime.fromisoformat(e["time"].replace("Z", "+00:00"))
        except (ValueError, KeyError):
            return datetime.min.replace(tzinfo=timezone.utc)

    events.sort(key=parse_time)
    return events


def build_leaderboard(registry, files, citations):
    """Build agent leaderboard data."""
    agents = {}

    # Start with registry data
    for agent_id, info in registry.items():
        agents[agent_id] = {
            "id": agent_id,
            "status": info.get("status", "unknown"),
            "last_seen": info.get("last_seen", ""),
            "focus": info.get("focus", ""),
            "contributions": info.get("contributions", 0),
            "files_published": 0,
            "citations_made": 0,
            "citations_received": 0,
            "messages_sent": 0,
        }

    # Count files per agent
    for f in files:
        agent = f.get("agent")
        if agent:
            if agent not in agents:
                agents[agent] = {
                    "id": agent,
                    "status": "unknown",
                    "last_seen": "",
                    "focus": "",
                    "contributions": 0,
                    "files_published": 0,
                    "citations_made": 0,
                    "citations_received": 0,
                    "messages_sent": 0,
                }
            agents[agent]["files_published"] += 1

    # Count citations
    for cite in citations:
        citer = cite.get("citer", "")
        cited = cite.get("cited", "")

        if citer:
            if citer not in agents:
                agents[citer] = {
                    "id": citer, "status": "unknown", "last_seen": "",
                    "focus": "", "contributions": 0, "files_published": 0,
                    "citations_made": 0, "citations_received": 0, "messages_sent": 0,
                }
            agents[citer]["citations_made"] += 1

        if cited:
            if cited not in agents:
                agents[cited] = {
                    "id": cited, "status": "unknown", "last_seen": "",
                    "focus": "", "contributions": 0, "files_published": 0,
                    "citations_made": 0, "citations_received": 0, "messages_sent": 0,
                }
            agents[cited]["citations_received"] += 1

    # Count messages
    messages_file = swarm_root / "board" / "messages.jsonl"
    messages = parse_jsonl(messages_file)
    for msg in messages:
        sender = msg.get("from", "")
        if sender:
            if sender not in agents:
                agents[sender] = {
                    "id": sender, "status": "unknown", "last_seen": "",
                    "focus": "", "contributions": 0, "files_published": 0,
                    "citations_made": 0, "citations_received": 0, "messages_sent": 0,
                }
            agents[sender]["messages_sent"] += 1

    return list(agents.values())


def compute_overview(registry, files, citations, messages):
    """Compute overview statistics."""
    total_agents = len(registry)
    active_agents = sum(1 for info in registry.values() if info.get("status") == "active")
    total_files = len(files)
    total_citations = len(citations)
    total_messages = len(messages)

    # Count unique agents across all sources
    all_agents = set()
    for agent_id in registry:
        all_agents.add(agent_id)
    for f in files:
        if f.get("agent"):
            all_agents.add(f["agent"])
    for cite in citations:
        all_agents.add(cite.get("citer", ""))
        all_agents.add(cite.get("cited", ""))
    for msg in messages:
        all_agents.add(msg.get("from", ""))
    all_agents.discard("")
    all_agents.discard("all")

    # File counts by category
    files_by_category = {}
    for f in files:
        cat = f.get("category", "unknown")
        files_by_category[cat] = files_by_category.get(cat, 0) + 1

    return {
        "total_agents": len(all_agents),
        "active_agents": active_agents,
        "registered_agents": total_agents,
        "total_commons_files": total_files,
        "total_citations": total_citations,
        "total_messages": total_messages,
        "files_by_category": files_by_category,
    }


def main():
    global swarm_root
    swarm_root = find_swarm_root()
    print(f"Swarm root: {swarm_root}")

    # Verify root looks correct
    commons_dir = swarm_root / "commons"
    if not commons_dir.exists():
        print(f"ERROR: commons directory not found at {commons_dir}")
        sys.exit(1)

    # Load data sources
    print("Loading registry...")
    registry = parse_json(swarm_root / "registry.json")

    print("Loading citations...")
    citations = parse_jsonl(swarm_root / "citations.jsonl")

    print("Loading messages...")
    messages = parse_jsonl(swarm_root / "board" / "messages.jsonl")

    print("Loading leaderboard...")
    leaderboard_data = parse_json(swarm_root / "vitals" / "leaderboard.json")

    print("Scanning commons...")
    files = scan_commons(commons_dir)

    # Build derived data
    print("Building citation network...")
    citation_network = build_citation_network(citations)

    print("Building activity timeline...")
    timeline = build_activity_timeline(messages, files, citations)

    print("Building leaderboard...")
    leaderboard = build_leaderboard(registry, files, citations)

    print("Computing overview...")
    overview = compute_overview(registry, files, citations, messages)

    # Sort messages by time (newest first)
    messages_sorted = sorted(
        messages,
        key=lambda m: m.get("time", ""),
        reverse=True,
    )

    # Assemble all data
    data = {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "swarm_root": str(swarm_root),
        "overview": overview,
        "registry": registry,
        "citations": citations,
        "messages": messages_sorted,
        "files": files,
        "citation_network": citation_network,
        "timeline": timeline,
        "leaderboard": leaderboard,
        "leaderboard_raw": leaderboard_data,
    }

    # Write data.js
    output_dir = Path(__file__).resolve().parent
    output_path = output_dir / "data.js"

    print(f"Writing {output_path}...")
    with open(output_path, "w", encoding="utf-8") as f:
        f.write("// Auto-generated by generate_data.py\n")
        f.write("// Do not edit manually - re-run the generator script\n\n")
        f.write("window.SWARM_DATA = ")
        json.dump(data, f, indent=2, ensure_ascii=False)
        f.write(";\n")

    print(f"Done! Generated data with:")
    print(f"  - {overview['total_agents']} total agents")
    print(f"  - {overview['total_commons_files']} commons files")
    print(f"  - {overview['total_citations']} citations")
    print(f"  - {overview['total_messages']} messages")
    print(f"  - {len(files)} files across {len(overview['files_by_category'])} categories")


if __name__ == "__main__":
    main()
