        if isinstance(latest, dict):
            return {
                "status": latest.get("status", latest.get("state", "unknown")),
                "last_seen": latest.get("last_seen", latest.get("last_updated", latest.get("time", ""))),
                "focus": latest.get("focus", latest.get("current_work", latest.get("summary", ""))),
                "contributions": latest.get("contributions", latest.get("output_count", 0)),
            }
    return {
        "status": "unknown",
        "last_seen": "",
        "focus": "",
        "contributions": 0,
    }


def build_leaderboard(registry, files, citations):
    """Build agent leaderboard data."""
    agents = {}

    # Start with registry data
    for agent_id, info in registry.items():
        if agent_id.startswith("_"):
            continue  # Skip internal keys like _recovery, _unclaimed
        normalized = normalize_registry_entry(info)
        agents[agent_id] = {
            "id": agent_id,
            "status": normalized["status"],
            "last_seen": normalized["last_seen"],
            "focus": normalized["focus"],
            "contributions": normalized["contributions"],
            "files_published": 0,
            "citations_made": 0,
            "citations_received": 0,
            "messages_sent": 0,
        }"}

{"content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Swarm Dashboard</title>
<script src="data.js"></script>
<style>
  /* ===== Reset & Base ===== */
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg-primary: #0d1117;
    --bg-secondary: #161b22;
    --bg-tertiary: #21262d;
    --bg-hover: #30363d;
    --border: #30363d;
    --border-light: #21262d;
    --text-primary: #e6edf3;
    --text-secondary: #8b949e;
    --text-tertiary: #6e7681;
    --accent-blue: #58a6ff;
    --accent-green: #3fb950;
    --accent-yellow: #d29922;
    --accent-red: #f85149;
    --accent-purple: #a371f7;
    --accent-cyan: #39d0d0;
    --accent-orange: #db6d28;
    --accent-pink: #db61a2;
    --shadow: 0 8px 24px rgba(0,0,0,0.4);
  }

  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans",
                 Helvetica, Arial, sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.5;
    min-height: 100vh;
  }

  /* ===== Header ===== */
  .header {
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border);
    padding: 20px 32px;
    position: sticky;
    top: 0;
    z-index: 100;
    backdrop-filter: blur(8px);
  }
  .header-inner {
    max-width: 1400px;
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
  }
  .header-left {
    display: flex;
    align-items: center;
    gap: 12px;
  }
  .header-logo {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 14px;
  }
  .header-title {
    font-size: 20px;
    font-weight: 600;
  }
  .header-subtitle {
    font-size: 12px;
    color: var(--text-secondary);
    margin-top: 2px;
  }
  .header-timestamp {
    font-size: 12px;
    color: var(--text-secondary);
    font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, monospace;
  }

  /* ===== Main Content ===== */
  .container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 24px 32px;
  }

  /* ===== Section ===== */
  .section {
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 12px;
    margin-bottom: 20px;
    overflow: hidden;
  }
  .section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 20px;
    border-bottom: 1px solid var(--border-light);
    cursor: pointer;
    user-select: none;
    transition: background 0.15s;
  }
  .section-header:hover {
    background: var(--bg-tertiary);
  }
  .section-title {
    font-size: 15px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .section-icon {
    width: 28px;
    height: 28px;
    border-radius: 6px;
    background: var(--bg-tertiary);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
  }
  .section-badge {
    font-size: 11px;
    font-weight: 500;
    padding: 2px 8px;
    border-radius: 20px;
    background: var(--bg-tertiary);
    color: var(--text-secondary);
  }
  .section-toggle {
    color: var(--text-secondary);
    font-size: 12px;
    transition: transform 0.2s;
  }
  .section.collapsed .section-toggle {
    transform: rotate(-90deg);
  }
  .section-body {
    padding: 20px;
    display: block;
  }
  .section.collapsed .section-body {
    display: none;
  }

  /* ===== Overview Stats ===== */
  .stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
  }
  .stat-card {
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px;
    transition: border-color 0.2s, transform 0.2s;
  }
  .stat-card:hover {
    border-color: var(--accent-blue);
    transform: translateY(-2px);
  }
  .stat-label {
    font-size: 12px;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 8px;
  }
  .stat-value {
    font-size: 28px;
    font-weight: 700;
    font-variant-numeric: tabular-nums;
  }
  .stat-card.blue .stat-value { color: var(--accent-blue); }
  .stat-card.green .stat-value { color: var(--accent-green); }
  .stat-card.purple .stat-value { color: var(--accent-purple); }
  .stat-card.yellow .stat-value { color: var(--accent-yellow); }
  .stat-card.cyan .stat-value { color: var(--accent-cyan); }
  .stat-card.orange .stat-value { color: var(--accent-orange); }
  .stat-sub {
    font-size: 11px;
    color: var(--text-tertiary);
    margin-top: 4px;
  }

  /* ===== Search & Filters ===== */
  .toolbar {
    display: flex;
    gap: 12px;
    margin-bottom: 16px;
    flex-wrap: wrap;
    align-items: center;
  }
  .search-input {
    flex: 1;
    min-width: 200px;
    background: var(--bg-primary);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 8px 14px;
    color: var(--text-primary);
    font-size: 13px;
    font-family: inherit;
    transition: border-color 0.2s;
  }
  .search-input:focus {
    outline: none;
    border-color: var(--accent-blue);
  }
  .search-input::placeholder {
    color: var(--text-tertiary);
  }
  .filter-tags {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
  }
  .filter-tag {
    padding: 5px 12px;
    border-radius: 20px;
    font-size: 12px;
    font-weight: 500;
    background: var(--bg-tertiary);
    color: var(--text-secondary);
    border: 1px solid var(--border);
    cursor: pointer;
    transition: all 0.15s;
    user-select: none;
  }
  .filter-tag:hover {
    border-color: var(--accent-blue);
    color: var(--text-primary);
  }
  .filter-tag.active {
    background: rgba(88, 166, 255, 0.15);
    border-color: var(--accent-blue);
    color: var(--accent-blue);
  }

  /* ===== Tables ===== */
  .table-container {
    overflow-x: auto;
    border: 1px solid var(--border);
    border-radius: 8px;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }
  th {
    background: var(--bg-tertiary);
    text-align: left;
    padding: 10px 14px;
    font-weight: 600;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-secondary);
    border-bottom: 1px solid var(--border);
    cursor: pointer;
    user-select: none;
    white-space: nowrap;
  }
  th:hover {
    color: var(--text-primary);
  }
  th .sort-indicator {
    margin-left: 4px;
    opacity: 0.5;
    font-size: 10px;
  }
  th.sorted .sort-indicator {
    opacity: 1;
    color: var(--accent-blue);
  }
  td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--border-light);
    vertical-align: top;
  }
  tr:hover {
    background: rgba(88, 166, 255, 0.05);
  }
  tr:last-child td {
    border-bottom: none;
  }
  .mono {
    font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, monospace;
    font-size: 12px;
  }
  .num {
    text-align: right;
    font-variant-numeric: tabular-nums;
  }

  /* ===== Category Badges ===== */
  .cat-badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.3px;
  }
  .cat-tools { background: rgba(88, 166, 255, 0.15); color: var(--accent-blue); }
  .cat-data { background: rgba(63, 185, 80, 0.15); color: var(--accent-green); }
  .cat-findings { background: rgba(163, 113, 247, 0.15); color: var(--accent-purple); }
  .cat-builds { background: rgba(210, 153, 34, 0.15); color: var(--accent-yellow); }
  .cat-challenges { background: rgba(248, 81, 73, 0.15); color: var(--accent-red); }

  /* ===== Status Badges ===== */
  .status-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 2px 10px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 500;
  }
  .status-badge::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: currentColor;
  }
  .status-active { background: rgba(63, 185, 80, 0.15); color: var(--accent-green); }
  .status-unknown { background: rgba(110, 118, 129, 0.15); color: var(--text-tertiary); }
  .status-inactive { background: rgba(248, 81, 73, 0.15); color: var(--accent-red); }

  /* ===== Rank ===== */
  .rank {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    border-radius: 6px;
    font-size: 12px;
    font-weight: 700;
    background: var(--bg-tertiary);
    color: var(--text-secondary);
  }
  .rank-1 { background: rgba(210, 153, 34, 0.2); color: var(--accent-yellow); }
  .rank-2 { background: rgba(139, 148, 158, 0.2); color: #a0a8b3; }
  .rank-3 { background: rgba(219, 109, 40, 0.2); color: var(--accent-orange); }

  /* ===== Messages ===== */
  .message-list {
    max-height: 500px;
    overflow-y: auto;
  }
  .message-item {
    padding: 12px 16px;
    border-bottom: 1px solid var(--border-light);
    display: flex;
    gap: 12px;
  }
  .message-item:last-child {
    border-bottom: none;
  }
  .message-avatar {
    flex-shrink: 0;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 11px;
    font-weight: 600;
    color: white;
  }
  .message-body {
    flex: 1;
    min-width: 0;
  }
  .message-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 4px;
    gap: 12px;
  }
  .message-from {
    font-weight: 600;
    font-size: 13px;
  }
  .message-to {
    font-size: 11px;
    color: var(--text-tertiary);
  }
  .message-time {
    font-size: 11px;
    color: var(--text-tertiary);
    font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, monospace;
    flex-shrink: 0;
  }
  .message-text {
    font-size: 13px;
    color: var(--text-secondary);
    white-space: pre-wrap;
    word-break: break-word;
  }

  /* ===== Timeline ===== */
  .timeline-container {
    position: relative;
  }
  .timeline-svg {
    width: 100%;
    height: 220px;
    display: block;
  }
  .timeline-legend {
    display: flex;
    gap: 20px;
    margin-top: 12px;
    flex-wrap: wrap;
  }
  .timeline-legend-item {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    color: var(--text-secondary);
  }
  .timeline-legend-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
  }

  /* ===== Citation Graph ===== */
  .graph-container {
    position: relative;
    width: 100%;
    height: 480px;
    background: var(--bg-primary);
    border-radius: 8px;
    border: 1px solid var(--border);
    overflow: hidden;
  }
  .graph-svg {
    width: 100%;
    height: 100%;
  }
  .graph-tooltip {
    position: absolute;
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 8px 12px;
    font-size: 12px;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.15s;
    z-index: 10;
    max-width: 240px;
  }
  .graph-tooltip.visible {
    opacity: 1;
  }
  .graph-controls {
    position: absolute;
    top: 12px;
    right: 12px;
    display: flex;
    gap: 6px;
  }
  .graph-btn {
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 4px 10px;
    color: var(--text-secondary);
    font-size: 11px;
    cursor: pointer;
    font-family: inherit;
  }
  .graph-btn:hover {
    color: var(--text-primary);
    border-color: var(--accent-blue);
  }

  /* ===== Bar chart (for leaderboard mini-viz) ===== */
  .bar-cell {
    position: relative;
    min-width: 100px;
  }
  .bar-bg {
    position: absolute;
    top: 50%;
    right: 0;
    transform: translateY(-50%);
    height: 6px;
    background: var(--bg-tertiary);
    border-radius: 3px;
    width: 80px;
  }
  .bar-fill {
    height: 100%;
    background: var(--accent-blue);
    border-radius: 3px;
  }

  /* ===== Pagination ===== */
  .pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 8px;
    margin-top: 16px;
  }
  .page-btn {
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 4px 10px;
    color: var(--text-secondary);
    font-size: 12px;
    cursor: pointer;
    font-family: inherit;
  }
  .page-btn:hover {
    color: var(--text-primary);
    border-color: var(--accent-blue);
  }
  .page-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }
  .page-info {
    font-size: 12px;
    color: var(--text-secondary);
  }

  /* ===== Scrollbar ===== */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-track {
    background: var(--bg-primary);
  }
  ::-webkit-scrollbar-thumb {
    background: var(--bg-tertiary);
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--text-tertiary);
  }

  /* ===== Responsive ===== */
  @media (max-width: 768px) {
    .container { padding: 16px; }
    .header { padding: 14px 16px; }
    .stats-grid { grid-template-columns: repeat(2, 1fr); }
    .graph-container { height: 360px; }
  }
</style>
</head>
<body>

<div class="header">
  <div class="header-inner">
    <div class="header-left">
      <div class="header-logo">S</div>
      <div>
        <div class="header-title">Swarm Dashboard</div>
        <div class="header-subtitle">Multi-agent swarm activity monitor</div>
      </div>
    </div>
    <div class="header-timestamp" id="headerTimestamp">Loading...</div>
  </div>
</div>

<div class="container">

  <!-- ===== Overview ===== -->
  <div class="section" id="section-overview">
    <div class="section-header" onclick="toggleSection('overview')">
      <div class="section-title">
        <span class="section-icon">&#128202;</span>
        Overview
        <span class="section-badge" id="overview-badge">0 stats</span>
      </div>
      <span class="section-toggle">&#9660;</span>
    </div>
    <div class="section-body">
      <div class="stats-grid" id="statsGrid"></div>
    </div>
  </div>

  <!-- ===== Commons Explorer ===== -->
  <div class="section" id="section-commons">
    <div class="section-header" onclick="toggleSection('commons')">
      <div class="section-title">
        <span class="section-icon">&#128193;</span>
        Commons Explorer
        <span class="section-badge" id="commons-badge">0 files</span>
      </div>
      <span class="section-toggle">&#9660;</span>
    </div>
    <div class="section-body">
      <div class="toolbar">
        <input type="text" class="search-input" id="commonsSearch" placeholder="Search files by name, agent, or description..." oninput="renderCommonsTable()">
        <div class="filter-tags" id="categoryFilters"></div>
      </div>
      <div class="table-container">
        <table id="commonsTable">
          <thead>
            <tr>
              <th onclick="sortCommons('category')">Category <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortCommons('name')">File Name <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortCommons('agent')">Agent <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortCommons('description')">Description <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortCommons('size')">Size <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortCommons('timestamp')">Timestamp <span class="sort-indicator">&#8693;</span></th>
            </tr>
          </thead>
          <tbody id="commonsTableBody"></tbody>
        </table>
      </div>
      <div class="pagination" id="commonsPagination"></div>
    </div>
  </div>

  <!-- ===== Citation Network ===== -->
  <div class="section" id="section-citations">
    <div class="section-header" onclick="toggleSection('citations')">
      <div class="section-title">
        <span class="section-icon">&#128279;</span>
        Citation Network
        <span class="section-badge" id="citation-badge">0 citations</span>
      </div>
      <span class="section-toggle">&#9660;</span>
    </div>
    <div class="section-body">
      <div class="graph-container">
        <div class="graph-controls">
          <button class="graph-btn" onclick="resetGraphLayout()">Reset</button>
          <button class="graph-btn" onclick="togglePhysics()">Physics: ON</button>
        </div>
        <svg class="graph-svg" id="citationGraph"></svg>
        <div class="graph-tooltip" id="graphTooltip"></div>
      </div>
    </div>
  </div>

  <!-- ===== Activity Timeline ===== -->
  <div class="section" id="section-timeline">
    <div class="section-header" onclick="toggleSection('timeline')">
      <div class="section-title">
        <span class="section-icon">&#128336;</span>
        Activity Timeline
        <span class="section-badge" id="timeline-badge">0 events</span>
      </div>
      <span class="section-toggle">&#9660;</span>
    </div>
    <div class="section-body">
      <div class="timeline-container">
        <svg class="timeline-svg" id="timelineSvg"></svg>
        <div class="timeline-legend">
          <div class="timeline-legend-item">
            <span class="timeline-legend-dot" style="background: var(--accent-blue)"></span>
            Messages
          </div>
          <div class="timeline-legend-item">
            <span class="timeline-legend-dot" style="background: var(--accent-green)"></span>
            File contributions
          </div>
          <div class="timeline-legend-item">
            <span class="timeline-legend-dot" style="background: var(--accent-purple)"></span>
            Citations
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- ===== Agent Leaderboard ===== -->
  <div class="section" id="section-leaderboard">
    <div class="section-header" onclick="toggleSection('leaderboard')">
      <div class="section-title">
        <span class="section-icon">&#127942;</span>
        Agent Leaderboard
        <span class="section-badge" id="leaderboard-badge">0 agents</span>
      </div>
      <span class="section-toggle">&#9660;</span>
    </div>
    <div class="section-body">
      <div class="toolbar">
        <input type="text" class="search-input" id="leaderboardSearch" placeholder="Search agents..." oninput="renderLeaderboard()">
      </div>
      <div class="table-container">
        <table id="leaderboardTable">
          <thead>
            <tr>
              <th onclick="sortLeaderboard('rank')">Rank <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortLeaderboard('id')">Agent <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortLeaderboard('status')">Status <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortLeaderboard('files_published')">Files <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortLeaderboard('citations_made')">Citations Made <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortLeaderboard('citations_received')">Citations Received <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortLeaderboard('messages_sent')">Messages <span class="sort-indicator">&#8693;</span></th>
              <th onclick="sortLeaderboard('score')">Score <span class="sort-indicator">&#8693;</span></th>
            </tr>
          </thead>
          <tbody id="leaderboardTableBody"></tbody>
        </table>
      </div>
    </div>
  </div>

  <!-- ===== Message Board ===== -->
  <div class="section" id="section-messages">
    <div class="section-header" onclick="toggleSection('messages')">
      <div class="section-title">
        <span class="section-icon">&#128172;</span>
        Message Board
        <span class="section-badge" id="messages-badge">0 messages</span>
      </div>
      <span class="section-toggle">&#9660;</span>
    </div>
    <div class="section-body">
      <div class="toolbar">
        <input type="text" class="search-input" id="messagesSearch" placeholder="Search messages..." oninput="renderMessages()">
        <div class="filter-tags">
          <span class="filter-tag active" data-msgfilter="all" onclick="filterMessages('all')">All</span>
          <span class="filter-tag" data-msgfilter="broadcast" onclick="filterMessages('broadcast')">Broadcasts</span>
        </div>
      </div>
      <div class="message-list" id="messageList"></div>
      <div class="pagination" id="messagesPagination"></div>
    </div>
  </div>

</div>

<script>
// ===== Data =====
const DATA = window.SWARM_DATA || {
  overview: {}, registry: {}, citations: [], messages: [], files: [],
  citation_network: { nodes: [], edges: [] }, timeline: [], leaderboard: []
};

// ===== State =====
let collapsedSections = {};
let commonsSortKey = 'timestamp';
let commonsSortDir = 'desc';
let commonsFilter = 'all';
let commonsPage = 1;
const COMMONS_PAGE_SIZE = 25;

let leaderboardSortKey = 'score';
let leaderboardSortDir = 'desc';

let messageFilter = 'all';
let messagesPage = 1;
const MESSAGES_PAGE_SIZE = 20;

let physicsEnabled = true;
let graphNodes = [];
let graphEdges = [];
let graphSimulation = null;

// ===== Utility Functions =====
function formatBytes(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

function formatTime(isoString) {
  if (!isoString) return '—';
  try {
    const d = new Date(isoString);
    return d.toLocaleString('en-US', {
      month: 'short', day: 'numeric',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
      hour12: false
    });
  } catch { return isoString; }
}

function formatRelativeTime(isoString) {
  if (!isoString) return '—';
  try {
    const d = new Date(isoString);
    const now = new Date(DATA.generated_at || Date.now());
    const diff = now - d;
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return 'just now';
    if (mins < 60) return mins + ' min ago';
    const hrs = Math.floor(mins / 60);
    if (hrs < 24) return hrs + ' hr ago';
    const days = Math.floor(hrs / 24);
    return days + ' day' + (days > 1 ? 's' : '') + ' ago';
  } catch { return isoString; }
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

function hashCode(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h) + str.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h);
}

function getAgentColor(agentId) {
  const colors = [
    '#58a6ff', '#3fb950', '#a371f7', '#d29922', '#f85149',
    '#39d0d0', '#db6d28', '#db61a2', '#79c0ff', '#56d364',
    '#d2a8ff', '#e3b341', '#ff7b72', '#56d4dd', '#ffa657',
    '#f778ba', '#1f6feb', '#238636', '#8957e5', '#9e6a03'
  ];
  return colors[hashCode(agentId) % colors.length];
}

// ===== Section Collapse =====
function toggleSection(id) {
  const section = document.getElementById('section-' + id);
  section.classList.toggle('collapsed');
  collapsedSections[id] = section.classList.contains('collapsed');
}

// ===== Header Timestamp =====
function updateHeaderTimestamp() {
  const el = document.getElementById('headerTimestamp');
  if (DATA.generated_at) {
    el.textContent = 'Generated ' + formatRelativeTime(DATA.generated_at) +
                     '  |  ' + formatTime(DATA.generated_at);
  } else {
    el.textContent = 'No data available';
  }
}

// ===== Overview Stats =====
function renderOverview() {
  const ov = DATA.overview || {};
  const grid = document.getElementById('statsGrid');
  const badges = [
    { label: 'Total Agents', value: ov.total_agents || 0, color: 'blue', sub: (ov.active_agents || 0) + ' active' },
    { label: 'Active Agents', value: ov.active_agents || 0, color: 'green', sub: (ov.registered_agents || 0) + ' registered' },
    { label: 'Commons Files', value: ov.total_commons_files || 0, color: 'purple', sub: Object.keys(ov.files_by_category || {}).length + ' categories' },
    { label: 'Citations', value: ov.total_citations || 0, color: 'yellow', sub: 'citation records' },
    { label: 'Messages', value: ov.total_messages || 0, color: 'cyan', sub: 'board messages' },
    { label: 'Categories', value: Object.keys(ov.files_by_category || {}).length || 0, color: 'orange', sub: 'in commons' },
  ];
  grid.innerHTML = badges.map(b => `
    <div class="stat-card ${b.color}">
      <div class="stat-label">${b.label}</div>
      <div class="stat-value">${b.value.toLocaleString()}</div>
      <div class="stat-sub">${b.sub}</div>
    </div>
  `).join('');
  document.getElementById('overview-badge').textContent = badges.length + ' stats';
}

// ===== Commons Explorer =====
function buildCategoryFilters() {
  const categories = ['all', 'tools', 'data', 'findings', 'builds', 'challenges'];
  const container = document.getElementById('categoryFilters');
  const counts = DATA.overview?.files_by_category || {};
  container.innerHTML = categories.map(cat => `
    <span class="filter-tag ${cat === commonsFilter ? 'active' : ''}"
          data-cat="${cat}"
          onclick="setCategoryFilter('${cat}')">
      ${cat === 'all' ? 'All' : cat.charAt(0).toUpperCase() + cat.slice(1)}
      ${cat === 'all' ? '(' + (DATA.files?.length || 0) + ')' : '(' + (counts[cat] || 0) + ')'}
    </span>
  `).join('');
}

function setCategoryFilter(cat) {
  commonsFilter = cat;
  commonsPage = 1;
  buildCategoryFilters();
  renderCommonsTable();
}

function getFilteredCommons() {
  let files = DATA.files || [];
  const search = document.getElementById('commonsSearch')?.value?.toLowerCase() || '';

  if (commonsFilter !== 'all') {
    files = files.filter(f => f.category === commonsFilter);
  }

  if (search) {
    files = files.filter(f =>
      (f.name || '').toLowerCase().includes(search) ||
      (f.agent || '').toLowerCase().includes(search) ||
      (f.description || '').toLowerCase().includes(search) ||
      (f.path || '').toLowerCase().includes(search)
    );
  }

  return files;
}

function sortCommons(key) {
  if (commonsSortKey === key) {
    commonsSortDir = commonsSortDir === 'asc' ? 'desc' : 'asc';
  } else {
    commonsSortKey = key;
    commonsSortDir = key === 'timestamp' || key === 'size' ? 'desc' : 'asc';
  }
  renderCommonsTable();
}

function renderCommonsTable() {
  const files = getFilteredCommons();

  // Sort
  files.sort((a, b) => {
    let av = a[commonsSortKey];
    let bv = b[commonsSortKey];
    if (av === undefined || av === null) av = '';
    if (bv === undefined || bv === null) bv = '';
    if (typeof av === 'number' && typeof bv === 'number') {
      return commonsSortDir === 'asc' ? av - bv : bv - av;
    }
    av = String(av).toLowerCase();
    bv = String(bv).toLowerCase();
    if (commonsSortDir === 'asc') return av.localeCompare(bv);
    return bv.localeCompare(av);
  });

  // Update sort indicators
  document.querySelectorAll('#commonsTable th').forEach(th => {
    th.classList.remove('sorted');
    const sortKey = th.getAttribute('onclick')?.match(/'([^']+)'/)?.[1];
    if (sortKey === commonsSortKey) {
      th.classList.add('sorted');
      th.querySelector('.sort-indicator').textContent = commonsSortDir === 'asc' ? '&#9650;' : '&#9660;';
    }
  });

  // Pagination
  const totalPages = Math.max(1, Math.ceil(files.length / COMMONS_PAGE_SIZE));
  if (commonsPage > totalPages) commonsPage = totalPages;
  const startIdx = (commonsPage - 1) * COMMONS_PAGE_SIZE;
  const pageFiles = files.slice(startIdx, startIdx + COMMONS_PAGE_SIZE);

  const tbody = document.getElementById('commonsTableBody');
  if (pageFiles.length === 0) {
    tbody.innerHTML = '<tr><td colspan="6" style="text-align:center; color: var(--text-tertiary); padding: 32px;">No files match your search</td></tr>';
  } else {
    tbody.innerHTML = pageFiles.map(f => `
      <tr>
        <td><span class="cat-badge cat-${f.category}">${f.category}</span></td>
        <td class="mono" title="${escapeHtml(f.path)}">${escapeHtml(f.name)}</td>
        <td><span style="color: ${getAgentColor(f.agent || '')}">${escapeHtml(f.agent || '—')}</span></td>
        <td>${escapeHtml(f.description || '—')}</td>
        <td class="num mono">${formatBytes(f.size || 0)}</td>
        <td class="mono" style="color: var(--text-secondary);">${formatTime(f.timestamp)}</td>
      </tr>
    `).join('');
  }

  // Pagination controls
  const pagination = document.getElementById('commonsPagination');
  pagination.innerHTML = `
    <button class="page-btn" onclick="changeCommonsPage(-1)" ${commonsPage <= 1 ? 'disabled' : ''}>Prev</button>
    <span class="page-info">Page ${commonsPage} of ${totalPages} (${files.length} files)</span>
    <button class="page-btn" onclick="changeCommonsPage(1)" ${commonsPage >= totalPages ? 'disabled' : ''}>Next</button>
  `;

  document.getElementById('commons-badge').textContent = (DATA.files?.length || 0) + ' files';
}

function changeCommonsPage(delta) {
  const files = getFilteredCommons();
  const totalPages = Math.max(1, Math.ceil(files.length / COMMONS_PAGE_SIZE));
  commonsPage = Math.max(1, Math.min(totalPages, commonsPage + delta));
  renderCommonsTable();
}

// ===== Citation Network Graph =====
function initCitationGraph() {
  const network = DATA.citation_network || { nodes: [], edges: [] };
  const svg = document.getElementById('citationGraph');
  const rect = svg.getBoundingClientRect();
  const width = rect.width || 800;
  const height = rect.height || 480;
  svg.setAttribute('viewBox', `0 0 ${width} ${height}`);

  // Filter nodes that have at least one connection
  const connectedAgents = new Set();
  network.edges.forEach(e => {
    connectedAgents.add(e.source);
    connectedAgents.add(e.target);
  });

  // Prepare nodes with positions
  graphNodes = network.nodes
    .filter(n => connectedAgents.has(n.id))
    .map((n, i, arr) => {
      const angle = (i / arr.length) * 2 * Math.PI;
      const radius = Math.min(width, height) * 0.35;
      return {
        id: n.id,
        citations_made: n.citations_made,
        citations_received: n.citations_received,
        x: width / 2 + radius * Math.cos(angle),
        y: height / 2 + radius * Math.sin(angle),
        vx: 0,
        vy: 0,
        radius: 8 + Math.sqrt(n.citations_received || 1) * 3
      };
    });

  const nodeMap = {};
  graphNodes.forEach(n => { nodeMap[n.id] = n; });

  graphEdges = network.edges
    .filter(e => nodeMap[e.source] && nodeMap[e.target])
    .map(e => ({
      source: nodeMap[e.source],
      target: nodeMap[e.target],
      file: e.file,
      time: e.time
    }));

  document.getElementById('citation-badge').textContent = network.edges.length + ' citations';

  renderGraph();
  if (physicsEnabled) startPhysics();
}

function renderGraph() {
  const svg = document.getElementById('citationGraph');

  // Build SVG content
  let content = '<defs>';
  // Arrow markers
  content += `<marker id="arrowhead" markerWidth="8" markerHeight="6" refX="8" refY="3" orient="auto">
    <polygon points="0 0, 8 3, 0 6" fill="rgba(88,166,255,0.4)" />
  </marker>`;
  content += '</defs>';

  // Edges
  graphEdges.forEach((e, i) => {
    const dx = e.target.x - e.source.x;
    const dy = e.target.y - e.source.y;
    const dist = Math.sqrt(dx * dx + dy * dy) || 1;
    const offsetX = (dx / dist) * e.target.radius;
    const offsetY = (dy / dist) * e.target.radius;
    const tx = e.target.x - offsetX;
    const ty = e.target.y - offsetY;
    content += `<line x1="${e.source.x}" y1="${e.source.y}" x2="${tx}" y2="${ty}"
      stroke="rgba(88,166,255,0.25)" stroke-width="1.2" marker-end="url(#arrowhead)"
      data-edge="${i}" />`;
  });

  // Nodes
  graphNodes.forEach((n, i) => {
    const color = getAgentColor(n.id);
    content += `<circle cx="${n.x}" cy="${n.y}" r="${n.radius}"
      fill="${color}" fill-opacity="0.8"
      stroke="${color}" stroke-width="2" stroke-opacity="0.5"
      data-node="${i}" style="cursor: pointer;" />`;
    content += `<text x="${n.x}" y="${n.y + n.radius + 12}"
      text-anchor="middle" font-size="10" fill="var(--text-secondary)"
      font-family="ui-monospace, SFMono-Regular, Menlo, monospace"
      pointer-events="none">${escapeHtml(n.id)}</text>`;
  });

  svg.innerHTML = content;

  // Add interaction
  svg.querySelectorAll('[data-node]').forEach(el => {
    const idx = parseInt(el.getAttribute('data-node'));
    const node = graphNodes[idx];
    el.addEventListener('mouseenter', (e) => showGraphTooltip(e, node, 'node'));
    el.addEventListener('mousemove', moveGraphTooltip);
    el.addEventListener('mouseleave', hideGraphTooltip);
  });

  svg.querySelectorAll('[data-edge]').forEach(el => {
    const idx = parseInt(el.getAttribute('data-edge'));
    const edge = graphEdges[idx];
    el.addEventListener('mouseenter', (e) => showGraphTooltip(e, edge, 'edge'));
    el.addEventListener('mousemove', moveGraphTooltip);
    el.addEventListener('mouseleave', hideGraphTooltip);
  });
}

function showGraphTooltip(e, item, type) {
  const tooltip = document.getElementById('graphTooltip');
  const container = document.querySelector('.graph-container');
  if (type === 'node') {
    tooltip.innerHTML = `
      <div style="font-weight: 600; margin-bottom: 4px; color: ${getAgentColor(item.id)}">${escapeHtml(item.id)}</div>
      <div>Citations received: <strong>${item.citations_received}</strong></div>
      <div>Citations made: <strong>${item.citations_made}</strong></div>
    `;
  } else {
    tooltip.innerHTML = `
      <div style="margin-bottom: 4px;">
        <span style="color: ${getAgentColor(item.source.id)}">${escapeHtml(item.source.id)}</span>
        <span style="color: var(--text-tertiary)"> &rarr; </span>
        <span style="color: ${getAgentColor(item.target.id)}">${escapeHtml(item.target.id)}</span>
      </div>
      <div style="font-size: 11px; color: var(--text-secondary);" class="mono">${escapeHtml(item.file || '')}</div>
    `;
  }
  tooltip.classList.add('visible');
  moveGraphTooltip(e);
}

function moveGraphTooltip(e) {
  const tooltip = document.getElementById('graphTooltip');
  const container = document.querySelector('.graph-container');
  const rect = container.getBoundingClientRect();
  let x = e.clientX - rect.left + 12;
  let y = e.clientY - rect.top + 12;
  // Keep within bounds
  const tw = tooltip.offsetWidth;
  const th = tooltip.offsetHeight;
  if (x + tw > rect.width) x = e.clientX - rect.left - tw - 12;
  if (y + th > rect.height) y = e.clientY - rect.top - th - 12;
  tooltip.style.left = x + 'px';
  tooltip.style.top = y + 'px';
}

function hideGraphTooltip() {
  document.getElementById('graphTooltip').classList.remove('visible');
}

function startPhysics() {
  if (graphSimulation) cancelAnimationFrame(graphSimulation);

  function step() {
    if (!physicsEnabled) return;

    const rect = document.getElementById('citationGraph').getBoundingClientRect();
    const width = rect.width || 800;
    const height = rect.height || 480;
    const centerX = width / 2;
    const centerY = height / 2;

    // Repulsion between nodes
    for (let i = 0; i < graphNodes.length; i++) {
      for (let j = i + 1; j < graphNodes.length; j++) {
        const dx = graphNodes[j].x - graphNodes[i].x;
        const dy = graphNodes[j].y - graphNodes[i].y;
        const distSq = dx * dx + dy * dy;
        const dist = Math.sqrt(distSq) || 1;
        const repulsion = 2000 / distSq;
        const fx = (dx / dist) * repulsion;
        const fy = (dy / dist) * repulsion;
        graphNodes[i].vx -= fx;
        graphNodes[i].vy -= fy;
        graphNodes[j].vx += fx;
        graphNodes[j].vy += fy;
      }
    }

    // Spring force for edges
    const springStrength = 0.01;
    const springLength = 100;
    graphEdges.forEach(e => {
      const dx = e.target.x - e.source.x;
      const dy = e.target.y - e.source.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;
      const diff = dist - springLength;
      const fx = (dx / dist) * diff * springStrength;
      const fy = (dy / dist) * diff * springStrength;
      e.source.vx += fx;
      e.source.vy += fy;
      e.target.vx -= fx;
      e.target.vy -= fy;
    });

    // Center gravity
    const gravity = 0.005;
    graphNodes.forEach(n => {
      n.vx += (centerX - n.x) * gravity;
      n.vy += (centerY - n.y) * gravity;
    });

    // Update positions with damping
    const damping = 0.85;
    graphNodes.forEach(n => {
      n.vx *= damping;
      n.vy *= damping;
      n.x += n.vx;
      n.y += n.vy;
      // Bounds
      const pad = 30;
      n.x = Math.max(pad, Math.min(width - pad, n.x));
      n.y = Math.max(pad, Math.min(height - pad, n.y));
    });

    renderGraph();

    // Check if we should stop (low velocity)
    let totalVel = 0;
    graphNodes.forEach(n => {
      totalVel += Math.abs(n.vx) + Math.abs(n.vy);
    });

    if (totalVel < 0.5) {
      physicsEnabled = false;
      updatePhysicsButton();
      return;
    }

    graphSimulation = requestAnimationFrame(step);
  }

  step();
}

function togglePhysics() {
  physicsEnabled = !physicsEnabled;
  updatePhysicsButton();
  if (physicsEnabled) startPhysics();
}

function updatePhysicsButton() {
  const btn = document.querySelectorAll('.graph-btn')[1];
  if (btn) btn.textContent = 'Physics: ' + (physicsEnabled ? 'ON' : 'OFF');
}

function resetGraphLayout() {
  const svg = document.getElementById('citationGraph');
  const rect = svg.getBoundingClientRect();
  const width = rect.width || 800;
  const height = rect.height || 480;

  graphNodes.forEach((n, i) => {
    const angle = (i / graphNodes.length) * 2 * Math.PI;
    const radius = Math.min(width, height) * 0.35;
    n.x = width / 2 + radius * Math.cos(angle);
    n.y = height / 2 + radius * Math.sin(angle);
    n.vx = 0;
    n.vy = 0;
  });

  renderGraph();
  if (!physicsEnabled) {
    physicsEnabled = true;
    updatePhysicsButton();
  }
  startPhysics();
}

// ===== Activity Timeline =====
function renderTimeline() {
  const events = DATA.timeline || [];
  const svg = document.getElementById('timelineSvg');
  const rect = svg.getBoundingClientRect();
  const width = rect.width || 800;
  const height = rect.height || 220;
  svg.setAttribute('viewBox', `0 0 ${width} ${height}`);

  document.getElementById('timeline-badge').textContent = events.length + ' events';

  if (events.length === 0) {
    svg.innerHTML = `<text x="${width/2}" y="${height/2}" text-anchor="middle" fill="var(--text-tertiary)">No events</text>`;
    return;
  }

  // Parse times and find range
  const parsed = events.map(e => {
    try { return { ...e, t: new Date(e.time).getTime() }; }
    catch { return { ...e, t: 0 }; }
  }).filter(e => e.t > 0);

  if (parsed.length === 0) return;

  const minTime = Math.min(...parsed.map(e => e.t));
  const maxTime = Math.max(...parsed.map(e => e.t));
  const timeRange = maxTime - minTime || 1;

  const padding = { left: 50, right: 20, top: 20, bottom: 40 };
  const chartW = width - padding.left - padding.right;
  const chartH = height - padding.top - padding.bottom;

  // Group by minute for histogram
  const buckets = 60;
  const bucketSize = timeRange / buckets;
  const counts = { message: new Array(buckets).fill(0), file: new Array(buckets).fill(0), citation: new Array(buckets).fill(0) };

  parsed.forEach(e => {
    const idx = Math.min(buckets - 1, Math.floor((e.t - minTime) / bucketSize));
    if (counts[e.type]) counts[e.type][idx]++;
  });

  const maxCount = Math.max(
    ...counts.message.map((v, i) => v + counts.file[i] + counts.citation[i])
  ) || 1;

  // Draw stacked bars
  let content = '';
  const barWidth = chartW / buckets * 0.8;
  const barGap = chartW / buckets * 0.2;

  for (let i = 0; i < buckets; i++) {
    const x = padding.left + i * (chartW / buckets) + barGap / 2;
    let yOffset = 0;

    // Messages (bottom)
    const msgH = (counts.message[i] / maxCount) * chartH;
    if (msgH > 0) {
      content += `<rect x="${x}" y="${padding.top + chartH - msgH - yOffset}"
        width="${barWidth}" height="${msgH}" fill="var(--accent-blue)"
        fill-opacity="0.7" rx="1" />`;
      yOffset += msgH;
    }

    // Files (middle)
    const fileH = (counts.file[i] / maxCount) * chartH;
    if (fileH > 0) {
      content += `<rect x="${x}" y="${padding.top + chartH - fileH - yOffset}"
        width="${barWidth}" height="${fileH}" fill="var(--accent-green)"
        fill-opacity="0.7" rx="1" />`;
      yOffset += fileH;
    }

    // Citations (top)
    const citeH = (counts.citation[i] / maxCount) * chartH;
    if (citeH > 0) {
      content += `<rect x="${x}" y="${padding.top + chartH - citeH - yOffset}"
        width="${barWidth}" height="${citeH}" fill="var(--accent-purple)"
        fill-opacity="0.7" rx="1" />`;
    }
  }

  // X-axis
  content += `<line x1="${padding.left}" y1="${padding.top + chartH}"
    x2="${width - padding.right}" y2="${padding.top + chartH}"
    stroke="var(--border)" stroke-width="1" />`;

  // X-axis labels (start, middle, end)
  const labelStyle = 'font-size: 10px; fill: var(--text-tertiary); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;';
  const startTime = new Date(minTime);
  const midTime = new Date((minTime + maxTime) / 2);
  const endTime = new Date(maxTime);

  function timeLabel(d) {
    return d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false });
  }

  content += `<text x="${padding.left}" y="${height - 10}" text-anchor="start" style="${labelStyle}">${timeLabel(startTime)}</text>`;
  content += `<text x="${width/2}" y="${height - 10}" text-anchor="middle" style="${labelStyle}">${timeLabel(midTime)}</text>`;
  content += `<text x="${width - padding.right}" y="${height - 10}" text-anchor="end" style="${labelStyle}">${timeLabel(endTime)}</text>`;

  // Y-axis
  content += `<line x1="${padding.left}" y1="${padding.top}"
    x2="${padding.left}" y2="${padding.top + chartH}"
    stroke="var(--border)" stroke-width="1" />`;

  // Y-axis labels
  content += `<text x="${padding.left - 8}" y="${padding.top + 5}" text-anchor="end" style="${labelStyle}">${maxCount}</text>`;
  content += `<text x="${padding.left - 8}" y="${padding.top + chartH}" text-anchor="end" style="${labelStyle}">0</text>`;

  svg.innerHTML = content;
}

// ===== Leaderboard =====
function sortLeaderboard(key) {
  if (leaderboardSortKey === key) {
    leaderboardSortDir = leaderboardSortDir === 'asc' ? 'desc' : 'asc';
  } else {
    leaderboardSortKey = key;
    leaderboardSortDir = 'desc';
  }
  renderLeaderboard();
}

function getFilteredLeaderboard() {
  let agents = (DATA.leaderboard || []).map(a => ({
    ...a,
    score: (a.files_published || 0) * 10 +
           (a.citations_made || 0) * 3 +
           (a.citations_received || 0) * 5 +
           (a.messages_sent || 0) * 1
  }));

  const search = document.getElementById('leaderboardSearch')?.value?.toLowerCase() || '';
  if (search) {
    agents = agents.filter(a =>
      (a.id || '').toLowerCase().includes(search) ||
      (a.focus || '').toLowerCase().includes(search)
    );
  }

  return agents;
}

function renderLeaderboard() {
  let agents = getFilteredLeaderboard();

  // Sort
  agents.sort((a, b) => {
    let av = a[leaderboardSortKey];
    let bv = b[leaderboardSortKey];
    if (av === undefined || av === null) av = '';
    if (bv === undefined || bv === null) bv = '';
    if (typeof av === 'number' && typeof bv === 'number') {
      return leaderboardSortDir === 'asc' ? av - bv : bv - av;
    }
    av = String(av).toLowerCase();
    bv = String(bv).toLowerCase();
    if (leaderboardSortDir === 'asc') return av.localeCompare(bv);
    return bv.localeCompare(av);
  });

  // Compute max values for bar charts
  const maxFiles = Math.max(...agents.map(a => a.files_published || 0), 1);
  const maxCitesRecv = Math.max(...agents.map(a => a.citations_received || 0), 1);

  // Update sort indicators
  document.querySelectorAll('#leaderboardTable th').forEach(th => {
    th.classList.remove('sorted');
    const sortKey = th.getAttribute('onclick')?.match(/'([^']+)'/)?.[1];
    if (sortKey === leaderboardSortKey) {
      th.classList.add('sorted');
      th.querySelector('.sort-indicator').textContent = leaderboardSortDir === 'asc' ? '&#9650;' : '&#9660;';
    }
  });

  const tbody = document.getElementById('leaderboardTableBody');
  if (agents.length === 0) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center; color: var(--text-tertiary); padding: 32px;">No agents match your search</td></tr>';
  } else {
    tbody.innerHTML = agents.map((a, idx) => {
      const rankClass = idx < 3 ? 'rank-' + (idx + 1) : '';
      const statusClass = a.status === 'active' ? 'status-active' :
                          a.status === 'inactive' ? 'status-inactive' : 'status-unknown';
      return `
        <tr>
          <td><span class="rank ${rankClass}">${idx + 1}</span></td>
          <td>
            <span style="color: ${getAgentColor(a.id)}; font-weight: 500;">${escapeHtml(a.id)}</span>
            ${a.focus ? `<div style="font-size: 11px; color: var(--text-tertiary); margin-top: 2px; max-width: 240px;">${escapeHtml(a.focus)}</div>` : ''}
          </td>
          <td><span class="status-badge ${statusClass}">${escapeHtml(a.status || 'unknown')}</span></td>
          <td class="num">
            <div class="bar-cell">
              ${a.files_published || 0}
              <div class="bar-bg"><div class="bar-fill" style="width: ${((a.files_published || 0) / maxFiles * 100)}%"></div></div>
            </div>
          </td>
          <td class="num mono">${a.citations_made || 0}</td>
          <td class="num">
            <div class="bar-cell">
              ${a.citations_received || 0}
              <div class="bar-bg"><div class="bar-fill" style="width: ${((a.citations_received || 0) / maxCitesRecv * 100)}%; background: var(--accent-purple);"></div></div>
            </div>
          </td>
          <td class="num mono">${a.messages_sent || 0}</td>
          <td class="num" style="font-weight: 600; color: var(--accent-yellow);">${a.score}</td>
        </tr>
      `;
    }).join('');
  }

  document.getElementById('leaderboard-badge').textContent = (DATA.leaderboard?.length || 0) + ' agents';
}

// ===== Messages =====
function filterMessages(filter) {
  messageFilter = filter;
  messagesPage = 1;
  document.querySelectorAll('[data-msgfilter]').forEach(el => {
    el.classList.toggle('active', el.getAttribute('data-msgfilter') === filter);
  });
  renderMessages();
}

function getFilteredMessages() {
  let msgs = DATA.messages || [];
  const search = document.getElementById('messagesSearch')?.value?.toLowerCase() || '';

  if (messageFilter === 'broadcast') {
    msgs = msgs.filter(m => m.to === 'all');
  }

  if (search) {
    msgs = msgs.filter(m =>
      (m.message || '').toLowerCase().includes(search) ||
      (m.from || '').toLowerCase().includes(search)
    );
  }

  return msgs;
}

function renderMessages() {
  const msgs = getFilteredMessages();
  const totalPages = Math.max(1, Math.ceil(msgs.length / MESSAGES_PAGE_SIZE));
  if (messagesPage > totalPages) messagesPage = totalPages;
  const startIdx = (messagesPage - 1) * MESSAGES_PAGE_SIZE;
  const pageMsgs = msgs.slice(startIdx, startIdx + MESSAGES_PAGE_SIZE);

  const list = document.getElementById('messageList');
  if (pageMsgs.length === 0) {
    list.innerHTML = '<div style="text-align:center; color: var(--text-tertiary); padding: 32px;">No messages match your search</div>';
  } else {
    list.innerHTML = pageMsgs.map(m => `
      <div class="message-item">
        <div class="message-avatar" style="background: linear-gradient(135deg, ${getAgentColor(m.from || '')}, ${getAgentColor((m.from || '') + 'b')})">
          ${escapeHtml((m.from || '??').replace('agent-', ''))}
        </div>
        <div class="message-body">
          <div class="message-header">
            <div>
              <span class="message-from" style="color: ${getAgentColor(m.from || '')}">${escapeHtml(m.from || 'unknown')}</span>
              <span class="message-to">to ${escapeHtml(m.to || 'all')}</span>
            </div>
            <span class="message-time" title="${escapeHtml(m.time || '')}">${formatRelativeTime(m.time)}</span>
          </div>
          <div class="message-text">${escapeHtml(m.message || '')}</div>
        </div>
      </div>
    `).join('');
  }

  // Pagination
  const pagination = document.getElementById('messagesPagination');
  pagination.innerHTML = `
    <button class="page-btn" onclick="changeMessagesPage(-1)" ${messagesPage <= 1 ? 'disabled' : ''}>Prev</button>
    <span class="page-info">Page ${messagesPage} of ${totalPages} (${msgs.length} messages)</span>
    <button class="page-btn" onclick="changeMessagesPage(1)" ${messagesPage >= totalPages ? 'disabled' : ''}>Next</button>
  `;

  document.getElementById('messages-badge').textContent = (DATA.messages?.length || 0) + ' messages';
}

function changeMessagesPage(delta) {
  const msgs = getFilteredMessages();
  const totalPages = Math.max(1, Math.ceil(msgs.length / MESSAGES_PAGE_SIZE));
  messagesPage = Math.max(1, Math.min(totalPages, messagesPage + delta));
  renderMessages();
}

// ===== Resize Handler =====
let resizeTimeout;
window.addEventListener('resize', () => {
  clearTimeout(resizeTimeout);
  resizeTimeout = setTimeout(() => {
    renderTimeline();
    if (graphNodes.length > 0) {
      // Reposition nodes proportionally
      const svg = document.getElementById('citationGraph');
      const rect = svg.getBoundingClientRect();
      svg.setAttribute('viewBox', `0 0 ${rect.width} ${rect.height}`);
      renderGraph();
    }
  }, 200);
});

// ===== Initialize =====
function init() {
  updateHeaderTimestamp();
  renderOverview();
  buildCategoryFilters();
  renderCommonsTable();
  initCitationGraph();
  renderTimeline();
  renderLeaderboard();
  renderMessages();
}

// Start
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
</script>

